<script setup>
import { Head, Link, useForm, usePage } from '@inertiajs/vue3';
import { ArrowUpRight, CheckCircle2, Mail, MapPin, MessageCircle, Phone, Send } from '@lucide/vue';
import { computed } from 'vue';
import StorefrontLayout from './StorefrontLayout.vue';
import { mapLocation } from './mapLocation';
const page = usePage();
const settings = computed(() => page.props.storeSettings || page.props.settings || {});
const phone = computed(() => settings.value.phone_one || settings.value.phone_two);
const email = computed(() => settings.value.email_one || settings.value.email_two);
const storeMap = computed(() => mapLocation(settings.value.maps));
const form = useForm({name:'', phone_number:'', subject:'', description:''});
function submit() { form.post('/contact', {preserveScroll:true, onSuccess:() => form.reset()}); }
</script>
<template>
    <Head title="Contact Us | FARBO" />
    <StorefrontLayout>
        <main class="contact-page">
            <div class="contact-shell">
                <nav class="contact-breadcrumb" aria-label="Breadcrumb"><Link href="/">Home</Link><span>/</span><span>Contact Us</span></nav>
                <header class="contact-heading"><span class="contact-eyebrow">LET'S TALK</span><h1>How can we help you?</h1><p>Questions about a product, an order or sourcing? Get in touch with the {{ settings.company_name || 'FARBO' }} team.</p></header>
                <div class="contact-methods">
                    <a v-if="phone" :href="`tel:${phone}`" class="contact-method"><span class="contact-icon"><Phone :size="21" /></span><div><span class="method-label">CALL OUR TEAM</span><strong>{{ phone }}</strong><small>Speak with us about your requirements</small></div><ArrowUpRight class="method-arrow" :size="18" /></a>
                    <a v-if="email" :href="`mailto:${email}`" class="contact-method"><span class="contact-icon"><Mail :size="21" /></span><div><span class="method-label">EMAIL US</span><strong>{{ email }}</strong><small>Send product details or your enquiry</small></div><ArrowUpRight class="method-arrow" :size="18" /></a>
                    <div v-if="settings.address" class="contact-method"><span class="contact-icon"><MapPin :size="21" /></span><div><span class="method-label">OUR ADDRESS</span><strong>{{ settings.address }}</strong><a v-if="storeMap.link" :href="storeMap.link" target="_blank" rel="noopener noreferrer" class="address-link">Get directions <ArrowUpRight :size="13" /></a></div></div>
                </div>
                <div v-if="page.props.flash?.success" class="contact-success" role="status"><CheckCircle2 :size="19" />{{ page.props.flash.success }}</div>
                <div class="contact-grid">
                    <section class="contact-card message-card"><span class="section-kicker">SEND AN ENQUIRY</span><h2>Leave us a message</h2><p class="section-intro">Share a few details so we can help you with the right information.</p>
                        <form @submit.prevent="submit" class="contact-form">
                            <label><span>Full name <b>*</b></span><input v-model="form.name" autocomplete="name" maxlength="160" placeholder="Your full name" required :aria-invalid="!!form.errors.name" /><small v-if="form.errors.name">{{ form.errors.name }}</small></label>
                            <label><span>Phone number <b>*</b></span><input v-model="form.phone_number" type="tel" autocomplete="tel" maxlength="40" placeholder="Your phone number" required :aria-invalid="!!form.errors.phone_number" /><small v-if="form.errors.phone_number">{{ form.errors.phone_number }}</small></label>
                            <label class="full-width"><span>Subject <b>*</b></span><input v-model="form.subject" maxlength="500" placeholder="Product enquiry, order support or sourcing" required :aria-invalid="!!form.errors.subject" /><small v-if="form.errors.subject">{{ form.errors.subject }}</small></label>
                            <label class="full-width"><span>Your message <b>*</b></span><textarea v-model="form.description" rows="6" maxlength="10000" placeholder="Tell us what you need. Include your order number or product model if relevant." required :aria-invalid="!!form.errors.description"></textarea><small v-if="form.errors.description">{{ form.errors.description }}</small></label>
                            <div class="form-footer full-width"><p>Your details will be used to respond to this enquiry.</p><button type="submit" :disabled="form.processing"><Send :size="17" />{{ form.processing ? 'Sending…' : 'Send message' }}</button></div>
                        </form>
                    </section>
                    <aside class="contact-aside">
                        <section class="contact-card help-card"><span class="contact-icon"><MessageCircle :size="24" /></span><h2>Need help choosing a part?</h2><p>Share the model, specifications or a photo of the part you need. Our team can help you check the right option before ordering.</p><a v-if="settings.whatsapp" :href="settings.whatsapp" target="_blank" rel="noopener noreferrer" class="whatsapp-link">Chat on WhatsApp <ArrowUpRight :size="17" /></a><Link v-else href="/categories" class="whatsapp-link">Browse our products <ArrowUpRight :size="17" /></Link></section>
                        <section v-if="storeMap.embed || storeMap.link" class="contact-card map-card"><div class="map-heading"><MapPin :size="18" /><h3>Find us</h3></div><iframe v-if="storeMap.embed" :src="storeMap.embed" title="FARBO location on Google Maps" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><a v-if="storeMap.link" :href="storeMap.link" target="_blank" rel="noopener noreferrer" class="map-link">Open in Google Maps <ArrowUpRight :size="16" /></a></section>
                    </aside>
                </div>
            </div>
        </main>
    </StorefrontLayout>
</template>
